EM_db* get_arr_em_db_tc( int EM_dataset) {
	if (EM_dataset == 62){	
	 	return arr_em_db_tc_ds62;
	}
	else if (EM_dataset == 633){		
		return arr_em_db_tc_ds633; 
	}
	else if (EM_dataset == 634){		
		return arr_em_db_tc_ds634;
	}
	else if (EM_dataset == 635){		
		return arr_em_db_tc_ds635;
	}
	else if (EM_dataset == 636){		
		return arr_em_db_tc_ds636;
	}
    else{
        printf(" Wrong endmember dataset, values should be 62, 633, 634, 635 or 636\n");
        printf(" -> using default ds-633 to avoid ugly crash\n"); 
        return arr_em_db_tc_ds633;   
    }
}

/* Select required thermodynamic database */
EM_db Access_EM_DB(int id, int EM_dataset) {
	EM_db Entry_EM;

	if (EM_dataset == 62){	
	 	Entry_EM = arr_em_db_tc_ds62[id]; 
	}
	else if (EM_dataset == 633){		
		Entry_EM = arr_em_db_tc_ds633[id]; 
	}
	else if (EM_dataset == 634){		
		Entry_EM = arr_em_db_tc_ds634[id]; 
	}
	else if (EM_dataset == 635){		
		Entry_EM = arr_em_db_tc_ds635[id]; 
	}
	else if (EM_dataset == 636){		
		Entry_EM = arr_em_db_tc_ds636[id]; 
	}
	else{
		printf(" Wrong endmember dataset, values should be 62, 633, 634, 635 or 636\n");
		printf(" -> using default ds-634 to avoid ugly crash\n");
		Entry_EM = arr_em_db_tc_ds634[id]; 
	}
	
	return Entry_EM;
}

/**************************************************************************************/
/* DEW2019 (Deep Earth Water) aqueous species database                                */
/*--------------------------------------------------------------------------          */
/* Sverjensky, D. A., Harrison, B., & Azzolini, D. (2014). Water in the deep Earth:   */
/* The dielectric constant and the solubilities of quartz and corundum to 60 kb and   */
/* 1200 C. Geochimica et Cosmochimica Acta, 129, 125-145.                             */
/* https://www.dewcommunity.org                                                        */
/*                                                                                     */
/* Comp[]/MuComp[] follow the canonical oxide_info order (SiO2,Al2O3,CaO,MgO,FeO,K2O, */
/* Na2O,TiO2,O,MnO,Cr2O3,H2O,CO2,S,Cl); [15] unused. Comp[] is the O-corrected         */
/* oxide-basis composition (mirrors DEW_19_gbase.jl's O-correction block, using       */
/* oxide_info's cation/oxygen-per-formula-unit constants). MuComp[]/input_4[0] (mu_Hp) */
/* together are the species' formation-reaction stoichiometry against the oxide       */
/* components + H+ (mirrors DEW_19_gbase.jl's mu_formula); DEW's Cl2O/SO2-basis       */
/* mu_formula entries are folded onto the elemental Cl/S components MAGEMin tracks    */
/* (Cl2O -> 2 Cl + 1 O, SO2 -> 1 S + 2 O - an exact stoichiometric identity).          */
/*                                                                                     */
/* Limited to the 120 (of 229) DEW2019 species whose element_formula is a subset of   */
/* MAGEMin's current oxide_info elements (Si,Al,Ca,Mg,Fe,K,Na,Ti,O,Mn,Cr,H,C,S,Cl) -   */
/* the remainder need oxide_info extended with trace elements before they can be      */
/* ported (see tools/DEW_implementation_plan.md).                                     */
/**************************************************************************************/

